// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
// Every failure the client raises is one of these, so a site can tell a missing
// entry (render a 404) from a bad key (fail the build) without parsing messages.

export class AstralError extends Error {
  override name = "AstralError";
}

/** The request never got an HTTP answer (DNS, refused connection, timeout). */
export class AstralNetworkError extends AstralError {
  override name = "AstralNetworkError";
  constructor(
    public readonly url: string,
    public readonly cause: unknown,
  ) {
    super(`Network error on ${url}: ${cause instanceof Error ? cause.message : String(cause)}`);
  }
}

/** The API answered with an error status. `code` is the API's error code when it sent one. */
export class AstralHttpError extends AstralError {
  override name = "AstralHttpError";
  constructor(
    public readonly status: number,
    public readonly code: string,
    public readonly url: string,
    public readonly body: unknown,
  ) {
    super(`Astral API ${status} (${code}) on ${url}`);
  }
}

export class AstralNotFoundError extends AstralHttpError {
  override name = "AstralNotFoundError";
}

/** 401 or 403: a missing, invalid or expired key, or a key without the needed capability. */
export class AstralAuthError extends AstralHttpError {
  override name = "AstralAuthError";
}

/** Reads the API's `{ error: "code" }` body and picks the error class for a status. */
export function httpError(status: number, url: string, body: unknown): AstralHttpError {
  const code = typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string" ? (body as { error: string }).error : `http_${status}`;
  if (status === 404) return new AstralNotFoundError(status, code, url, body);
  if (status === 401 || status === 403) return new AstralAuthError(status, code, url, body);
  return new AstralHttpError(status, code, url, body);
}
